CREATE TABLE Projects (ProjectId INT IDENTITY PRIMARY KEY, Code NVARCHAR(50) NOT NULL UNIQUE, Name NVARCHAR(200) NOT NULL, GoLiveDate DATE NULL, IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE ProjectBlocks (BlockId INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL REFERENCES Projects(ProjectId), BlockCode NVARCHAR(20) NOT NULL, Name NVARCHAR(250) NOT NULL, StartDate DATE NULL, DueDate DATE NULL, SortOrder INT NOT NULL DEFAULT 0);
CREATE TABLE Actions (ActionId INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL REFERENCES Projects(ProjectId), ExternalKey NVARCHAR(100) NULL, BlockCode NVARCHAR(20) NULL, Stream NVARCHAR(50) NULL, Topic NVARCHAR(300) NOT NULL, Description NVARCHAR(MAX) NULL, ActionPlan NVARCHAR(MAX) NULL, RaisedBy NVARCHAR(200) NULL, Priority NVARCHAR(30) NULL, StartDate DATE NULL, DueDate DATE NULL, Status NVARCHAR(50) NULL, Health NVARCHAR(50) NULL, CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), RowVersion ROWVERSION);
CREATE TABLE ActionOwners (ActionId INT NOT NULL REFERENCES Actions(ActionId) ON DELETE CASCADE, UserKey NVARCHAR(100) NOT NULL, IsPrimary BIT NOT NULL DEFAULT 0, PRIMARY KEY(ActionId,UserKey));
CREATE TABLE Decisions (DecisionId INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL REFERENCES Projects(ProjectId), ExternalKey NVARCHAR(100) NULL, Stream NVARCHAR(50) NULL, Decision NVARCHAR(500) NOT NULL, TargetDate DATE NULL, Owner NVARCHAR(200) NULL, Rationale NVARCHAR(MAX) NULL, Status NVARCHAR(50) NULL, CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Milestones (MilestoneId INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL REFERENCES Projects(ProjectId), Name NVARCHAR(300) NOT NULL, LevelCode NVARCHAR(20) NULL, Stream NVARCHAR(50) NULL, MilestoneDate DATE NOT NULL, Owner NVARCHAR(200) NULL, Status NVARCHAR(50) NULL);
CREATE TABLE RaidItems (RaidId INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL REFERENCES Projects(ProjectId), Type NVARCHAR(30) NOT NULL, Title NVARCHAR(500) NOT NULL, Impact NVARCHAR(30) NULL, Probability NVARCHAR(30) NULL, Owner NVARCHAR(200) NULL, DueDate DATE NULL, Mitigation NVARCHAR(MAX) NULL, Status NVARCHAR(50) NULL);
CREATE TABLE AuditLog (AuditId BIGINT IDENTITY PRIMARY KEY, ProjectId INT NULL, EntityType NVARCHAR(50) NOT NULL, EntityId NVARCHAR(100) NOT NULL, Action NVARCHAR(30) NOT NULL, ChangedBy NVARCHAR(250) NULL, ChangedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), BeforeJson NVARCHAR(MAX) NULL, AfterJson NVARCHAR(MAX) NULL);
CREATE TABLE ImportRuns (ImportRunId BIGINT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL REFERENCES Projects(ProjectId), SourceName NVARCHAR(300) NULL, Status NVARCHAR(30) NOT NULL, CreatedBy NVARCHAR(250) NULL, CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), AppliedAt DATETIME2 NULL, SummaryJson NVARCHAR(MAX) NULL);
CREATE UNIQUE INDEX UX_Actions_Project_ExternalKey ON Actions(ProjectId,ExternalKey) WHERE ExternalKey IS NOT NULL;
CREATE UNIQUE INDEX UX_Decisions_Project_ExternalKey ON Decisions(ProjectId,ExternalKey) WHERE ExternalKey IS NOT NULL;